<?php
require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../includes/seguridad.php';require_role(['administrador','profesor','estudiante']);require_once __DIR__.'/../models/CalificacionModel.php';$m=new CalificacionModel($pdo);$id=(int)($_GET['id']??0);$accion=$_GET['accion']??'listar';$puedeGestionar=puede_gestionar_academico();
if(es_estudiante()){$s=$pdo->prepare("SELECT e.id_estudiante FROM estudiantes e WHERE e.id_usuario=?");$s->execute([$_SESSION['id_usuario']]);$eid=$s->fetchColumn();$q=$pdo->prepare("SELECT c.*,CONCAT(u.nombre,' ',u.apellido) estudiante,cu.nombre_curso,cu.codigo FROM calificaciones c JOIN inscripciones i ON i.id_inscripcion=c.id_inscripcion JOIN estudiantes e ON e.id_estudiante=i.id_estudiante JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN cursos cu ON cu.id_curso=i.id_curso WHERE e.id_estudiante=? ORDER BY c.fecha DESC");$q->execute([$eid]);$registros=$q->fetchAll();$accion='listar';$id=0;}else{$registros=$m->obtenerTodas();}
if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['administrador','profesor']);validar_csrf();try{if(($_POST['accion']??'')==='eliminar'){$m->eliminar((int)$_POST['id']);flash('success','Calificación eliminada.');}else{if($id)$m->editar($id,$_POST);else$m->crear($_POST);flash('success',$id?'Calificación actualizada.':'Calificación registrada.');}}catch(Throwable $e){flash('error','No se pudo guardar la calificación.');}redir('/controllers/calificaciones.php');}$registro=($id&&$puedeGestionar)?$m->obtenerPorId($id):null;$tituloPagina='Notas y calificaciones';require __DIR__.'/../views/calificaciones/index.php';
